#!/usr/bin/env python3
"""Procedural layered scene renderer; all artwork is generated by the engine."""
import argparse, hashlib, json, random, shutil, subprocess, tempfile
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont, ImageFilter
PALETTES={"fantasia":("#091b38","#427e9e",(255,220,148)),"aventura":("#123347","#58a1b4",(248,198,112)),"mistério":("#11152c","#535d84",(211,220,255)),"terror":("#100d19","#593b47",(212,157,132)),"ficção científica":("#091c33","#236d89",(126,240,255)),"sci-fi":("#091c33","#236d89",(126,240,255)),"drama":("#302a38","#ad7a72",(252,207,160)),"default":("#0b2034","#397b91",(246,220,172))}
def font(n):
 for p in ['/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf','/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf']:
  if Path(p).exists(): return ImageFont.truetype(p,n)
 return ImageFont.load_default()
def color(s): return tuple(int(s.lstrip('#')[i:i+2],16) for i in (0,2,4))
def grad(size,a,b):
 w,h=size; im=Image.new('RGB',size); px=im.load(); a,b=color(a),color(b)
 for y in range(h):
  t=y/(h-1); c=tuple(int(a[k]*(1-t)+b[k]*t) for k in range(3))
  for x in range(w): px[x,y]=c
 return im.convert('RGBA')
def textwrap(draw,s,f,m):
 out=[]; line=''
 for word in str(s).split():
  trial=(line+' '+word).strip()
  if draw.textbbox((0,0),trial,font=f)[2]<=m: line=trial
  else:
   if line: out.append(line)
   line=word
 if line: out.append(line)
 return out
def draw_layers(scene,size,i,seedtxt,genre,folder):
 w,h=size; rng=random.Random(int(hashlib.sha256((seedtxt+str(i)).encode()).hexdigest()[:8],16)); top,bot,glow=PALETTES.get(genre.lower(),PALETTES['default'])
 bg=grad(size,top,bot); d=ImageDraw.Draw(bg,'RGBA'); sx=rng.randrange(w//4,3*w//4); sy=h//5; rad=w//9
 halo=Image.new('RGBA',size); hd=ImageDraw.Draw(halo); hd.ellipse((sx-rad*2,sy-rad*2,sx+rad*2,sy+rad*2),fill=(*glow,65)); bg=Image.alpha_composite(bg,halo.filter(ImageFilter.GaussianBlur(rad))); d=ImageDraw.Draw(bg)
 d.ellipse((sx-rad//2,sy-rad//2,sx+rad//2,sy+rad//2),fill=(*glow,220))
 for _ in range(80):
  x=rng.randrange(w); y=rng.randrange(h//2); d.ellipse((x,y,x+2,y+2),fill=(255,255,255,rng.randrange(70,190)))
 for layer in range(3):
  base=int(h*(.49+layer*.1)); pts=[(0,base)]; x=0
  while x<w:
   peak=min(w,x+rng.randint(w//12,w//5)); py=base-rng.randint(h//20,h//7); pts += [(x,base),(peak,py),(min(w,peak+w//10),base)]; x=peak+w//12
  pts.extend([(w,h),(0,h)]); d.polygon(pts,fill=[(30,50,78,125),(18,34,55,185),(7,16,28,225)][layer])
 mid=Image.new('RGBA',size); m=ImageDraw.Draw(mid); g=genre.lower()
 if any(x in g for x in ('fant','mist','avent','sci','ficção')):
  for x in range(0,w,w//10):
   bw=rng.randint(w//20,w//12); bh=rng.randint(h//7,h//3); base=int(h*.77)
   m.rectangle((x,base-bh,x+bw,base),fill=(7,15,28,185))
   if rng.random()<.5: m.polygon([(x,base-bh),(x+bw//2,base-bh-bh//4),(x+bw,base-bh)],fill=(7,15,28,185))
 else:
  for x in range(0,w,w//10):
   base=int(h*.82); crown=rng.randint(h//8,h//4); m.rectangle((x,base-crown//3,x+w//100,base),fill=(5,18,24,210)); m.ellipse((x-w//22,base-crown,x+w//22,base-crown//5),fill=(6,26,32,190))
 fg=Image.new('RGBA',size); f=ImageDraw.Draw(fg)
 for x in (w//20,19*w//20):
  for _ in range(5):
   y=rng.randint(h//2,h); ex=x+rng.choice([-1,1])*rng.randint(w//30,w//10); f.line((x,y,ex,y-rng.randint(20,130)),fill=(4,12,20,215),width=max(2,w//120))
 # Protagonist silhouette with a pose selected from the scene beat.
 character=Image.new('RGBA',size); cd=ImageDraw.Draw(character)
 cx=w//2+rng.randint(-w//5,w//5); ground=int(h*.84); scale=rng.uniform(.82,1.18)
 head=int(w*.075*scale); bodyh=int(h*.22*scale); shoulder=int(head*2.6)
 coat=(5,10,18,238); skin=(9,15,24,245); torso=int(bodyh*.62)
 scene_words=(str(scene.get('title',''))+' '+str(scene.get('text',''))+' '+str(scene.get('narration',''))).lower()
 if any(k in scene_words for k in ('corre','foge','persegue','corrida','run','escape')):
  pose='running'
 elif any(k in scene_words for k in ('senta','descansa','observa sentado','sitting')):
  pose='sitting'
 elif any(k in scene_words for k in ('aponta','mostra','indica','point')):
  pose='pointing'
 elif any(k in scene_words for k in ('caminha','anda','segue','viaja','walk')):
  pose='walking'
 else:
  pose=('walking','pointing','standing')[i%3]
 # Head and torso stay visually consistent between shots.
 head_y=ground-bodyh-head*2
 cd.ellipse((cx-head,head_y,cx+head,head_y+head*2),fill=skin)
 cd.polygon([(cx-shoulder,ground-bodyh+head),(cx+shoulder,ground-bodyh+head),
             (cx+head,ground-torso),(cx-head,ground-torso)],fill=coat)
 arm=max(5,head//2); leg=max(6,head//2)
 if pose=='running':
  cd.line((cx-shoulder,ground-bodyh+head*2,cx-shoulder-arm*2,ground-torso+head),fill=coat,width=arm)
  cd.line((cx+shoulder,ground-bodyh+head*2,cx+shoulder+arm,ground-bodyh+head*3),fill=coat,width=arm)
  cd.polygon([(cx-head,ground-torso),(cx-leg*2,ground-leg),(cx-leg*5,ground-leg//2),(cx,ground-torso)],fill=coat)
  cd.polygon([(cx+head,ground-torso),(cx+leg*3,ground-leg*3),(cx+leg*5,ground-leg*2),(cx,ground-torso)],fill=coat)
 elif pose=='sitting':
  cd.line((cx-shoulder,ground-bodyh+head*2,cx-shoulder-arm,ground-torso+head),fill=coat,width=arm)
  cd.line((cx+shoulder,ground-bodyh+head*2,cx+shoulder+arm,ground-torso+head),fill=coat,width=arm)
  cd.line((cx-head//2,ground-torso,cx+head*2,ground-torso+head*2),fill=coat,width=leg*2)
  cd.line((cx+head//2,ground-torso,cx+head*3,ground-torso+head*2),fill=coat,width=leg*2)
 else:
  if pose=='pointing':
   cd.line((cx-shoulder,ground-bodyh+head*2,cx-shoulder-arm,ground-torso+head),fill=coat,width=arm)
   cd.line((cx+shoulder,ground-bodyh+head*2,cx+shoulder+head*3,ground-bodyh+head),fill=coat,width=arm)
  else:
   cd.line((cx-shoulder,ground-bodyh+head*2,cx-shoulder-arm,ground-torso+head),fill=coat,width=arm)
   cd.line((cx+shoulder,ground-bodyh+head*2,cx+shoulder+arm,ground-torso+head),fill=coat,width=arm)
  cd.polygon([(cx-head,ground-torso),(cx-leg,ground),(cx,ground-torso)],fill=coat)
  cd.polygon([(cx+head,ground-torso),(cx+leg,ground),(cx,ground-torso)],fill=coat)
 character=character.filter(ImageFilter.GaussianBlur(1.0)); fg=Image.alpha_composite(fg,character)
 tx=Image.new('RGBA',size); t=ImageDraw.Draw(tx); margin=w//13; yy=h//7; title=str(scene.get('title',f'Scene {i}')); body=str(scene.get('text','')); tf=font(w//16); bf=font(w//27)
 t.rounded_rectangle((margin,yy,w-margin,h//2),radius=20,fill=(2,8,16,100),outline=(255,255,255,35),width=2); yy+=h//22
 for line in textwrap(t,title,tf,w-2*margin-25): t.text((margin+12,yy),line,font=tf,fill='white',stroke_width=1,stroke_fill=(0,0,0,120)); yy+=tf.size+6
 yy+=12
 for line in textwrap(t,body,bf,w-2*margin-25)[:5]: t.text((margin+12,yy),line,font=bf,fill=(232,242,249,240)); yy+=bf.size+8
 t.text((margin,h-h//20),f'CAPÍTULO {i:02d}',font=font(max(12,w//40)),fill=(230,240,250,175))
 for name,img in [('bg',bg),('mid',mid),('fg',fg),('txt',tx)]: img.save(folder/f'{name}_{i}.png')
def run(cmd): subprocess.run(cmd,check=True)
def main():
 p=argparse.ArgumentParser(); p.add_argument('--input',default='scenes.json'); p.add_argument('--output',default='output/video.mp4'); a=p.parse_args()
 if not shutil.which('ffmpeg'): raise SystemExit('FFmpeg ausente')
 data=json.loads(Path(a.input).read_text()); w=int(data.get('resolution',{}).get('width',720)); h=int(data.get('resolution',{}).get('height',1280)); fps=int(data.get('fps',24)); scenes=data.get('scenes',[])
 if not scenes: raise SystemExit('JSON sem cenas')
 idea=data.get('title',''); genre=data.get('genre','default'); out=Path(a.output); out.parent.mkdir(parents=True,exist_ok=True)
 with tempfile.TemporaryDirectory() as tmp:
  td=Path(tmp); clips=[]
  for i,s in enumerate(scenes,1):
   dur=max(1,float(s.get('duration',10))); frames=int(dur*fps); clip=td/f'clip_{i}.mp4'; draw_layers(s,(w,h),i,idea,genre,td)
   filt=f'[0:v]zoompan=z=\'min(zoom+0.0004,1.04)\':x=\'iw/2-(iw/zoom/2)+sin(on/50)*8\':y=\'ih/2-(ih/zoom/2)\':d={frames}:s={w}x{h}:fps={fps},format=rgba[b];[1:v]zoompan=z=\'min(zoom+0.0008,1.07)\':x=\'iw/2-(iw/zoom/2)+sin(on/35)*14\':y=\'ih/2-(ih/zoom/2)\':d={frames}:s={w}x{h}:fps={fps},format=rgba[m];[2:v]zoompan=z=\'min(zoom+0.0012,1.10)\':x=\'iw/2-(iw/zoom/2)+sin(on/25)*20\':y=\'ih/2-(ih/zoom/2)\':d={frames}:s={w}x{h}:fps={fps},format=rgba[f];[3:v]zoompan=z=1.0001:d={frames}:s={w}x{h}:fps={fps},format=rgba[t];[b][m]overlay=0:0[x];[x][f]overlay=0:0[y];[y][t]overlay=0:0,format=yuv420p[o]'
   run(['ffmpeg','-hide_banner','-loglevel','error','-y','-loop','1','-i',str(td/f'bg_{i}.png'),'-loop','1','-i',str(td/f'mid_{i}.png'),'-loop','1','-i',str(td/f'fg_{i}.png'),'-loop','1','-i',str(td/f'txt_{i}.png'),'-filter_complex',filt,'-map','[o]','-t',str(dur),'-r',str(fps),'-pix_fmt','yuv420p',str(clip)]); clips.append(clip)
  concat=td/'concat.txt'; concat.write_text('\n'.join("file '"+c.as_posix()+"'" for c in clips)+'\n')
  run(['ffmpeg','-hide_banner','-loglevel','error','-y','-f','concat','-safe','0','-i',str(concat),'-c','copy',str(out)])
 print('Render concluído:',out)
if __name__=='__main__': main()
